pub fn tokens(scheme: ColorScheme, scale: Scale) -> &'static Tokens {
    match (scheme, scale) {
        (ColorScheme::Light, Scale::Desktop) => &LIGHT_DESKTOP,
        (ColorScheme::Light, Scale::Mobile) => &LIGHT_MOBILE,
        (ColorScheme::Dark, Scale::Desktop) => &DARK_DESKTOP,
        (ColorScheme::Dark, Scale::Mobile) => &DARK_MOBILE,
    }
}
